 	Select(string, string, []string) (int, error)
 	Confirm(string, bool) (bool, error)
 }

 type CreateOptions struct {
 	HttpClient func() (*http.Client, error)
 	GitClient  *git.Client
 	Config     func() (gh.Config, error)
 	IO         *iostreams.IOStreams
 	Prompter   iprompter
